const avisosSinConfirmar = `-- name: AvisosSinConfirmar :many
SELECT id FROM mensajeria.avisos WHERE estado = 'en_cola' AND created_at < $1 ORDER BY created_at LIMIT 200
`

// En cola desde antes de @antes (sin acuse del canal): se dan por agotados.
func (q *Queries) AvisosSinConfirmar(ctx context.Context, antes time.Time) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, avisosSinConfirmar, antes)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

