const webhooksPorEnviar = `-- name: WebhooksPorEnviar :many
SELECT id, evento, empresa_id, payload, ocurrido_en, estado, intentos, proximo_intento, ultimo_error, conector_id, entregado_en, created_at, updated_at, conector_origen, carga_id FROM mensajeria.webhooks_salida
WHERE estado = 'pendiente' AND proximo_intento <= $1
ORDER BY proximo_intento
LIMIT $2
FOR UPDATE SKIP LOCKED
`

type WebhooksPorEnviarParams struct {
	Ahora  time.Time
	Limite int32
}

func (q *Queries) WebhooksPorEnviar(ctx context.Context, arg WebhooksPorEnviarParams) ([]MensajeriaWebhooksSalida, error) {
	rows, err := q.db.Query(ctx, webhooksPorEnviar, arg.Ahora, arg.Limite)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []MensajeriaWebhooksSalida
	for rows.Next() {
		var i MensajeriaWebhooksSalida
		if err := rows.Scan(
			&i.ID,
			&i.Evento,
			&i.EmpresaID,
			&i.Payload,
			&i.OcurridoEn,
			&i.Estado,
			&i.Intentos,
			&i.ProximoIntento,
			&i.UltimoError,
			&i.ConectorID,
			&i.EntregadoEn,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ConectorOrigen,
			&i.CargaID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

